<script setup>
import { computed, onMounted, ref } from 'vue';
import { createDefaultNuxtProgress, nuxtLessons, nuxtStages } from '~/lib/nuxt-course';
definePageMeta({ middleware: ['auth', 'law-auth'] });
const progress = ref(createDefaultNuxtProgress()); const loaded = ref(false);
const { isLoading, syncError, migratedFromBrowser, loadProgress } = useNuxtProgress();
onMounted(async () => { progress.value = await loadProgress(); loaded.value = true; });
const completedCount = computed(() => nuxtLessons.filter(item => progress.value.lessons[item.id]?.status === 'completed').length);
const reviewCount = computed(() => nuxtLessons.filter(item => progress.value.lessons[item.id]?.status === 'review').length);
const percent = computed(() => Math.round(completedCount.value / nuxtLessons.length * 100));
const totalMinutes = computed(() => Object.values(progress.value.lessons).reduce((sum, item) => sum + Number(item.minutes || 0), 0));
const continueLesson = computed(() => nuxtLessons.find(item => item.id === progress.value.lastLesson) || nuxtLessons.find(item => progress.value.lessons[item.id]?.status !== 'completed') || nuxtLessons[0]);
const statusLabel = item => ({ completed: '已理解', review: '待複習', learning: '學習中' }[progress.value.lessons[item.id]?.status] || '未開始');
</script>

<template>
  <main class="course-page">
    <header class="hero"><div><NuxtLink to="/admin/law-exam" class="back">← 回司律與私人學習後台</NuxtLink><p class="eyebrow">PRIVATE NUXT · VUE WORKBENCH</p><h1><span>Nuxt</span>.js / Vue.js</h1><p class="lead">先補齊 JavaScript 基礎，再從 Vue 3 元件與響應式一路走到 Nuxt SSR、Server API、測試與正式部署。</p><NuxtLink v-if="!isLoading" :to="`/admin/law-exam/nuxt/lesson/${continueLesson.id}`" class="continue">繼續：{{ continueLesson.title }} <b>→</b></NuxtLink></div><div class="logos" aria-hidden="true"><strong>▲</strong><b>V</b><small>直覺、漸進、全端整合</small></div></header>
    <section class="stats"><article><small>完整課程進度</small><strong>{{ percent }}%</strong><div class="bar"><i :style="{ width: `${percent}%` }"></i></div></article><article><small>已理解</small><strong>{{ completedCount }}<em>/{{ nuxtLessons.length }}</em></strong><p>全部課程皆已開放</p></article><article><small>待複習</small><strong>{{ reviewCount }}</strong><p>集中回顧標記內容</p></article><article><small>投入時間</small><strong>{{ totalMinutes }}<em> 分</em></strong><p>跨裝置同步累計</p></article></section>
    <section class="roadmap"><div class="heading"><div><p>LEARNING ROADMAP</p><h2>從 JavaScript 到全端 Nuxt</h2></div><span>六大階段、50 堂課與完整實作專案皆已開放。</span></div><div v-for="stage in nuxtStages" :key="stage.id" class="stage" :style="{ '--stage': stage.color }"><div class="stage-title"><span>{{ stage.number }}</span><div><h3>{{ stage.icon }} {{ stage.title }}</h3><p>{{ stage.subtitle }}</p></div></div><div class="lesson-grid"><NuxtLink v-for="item in nuxtLessons.filter(lesson => lesson.stage === stage.id)" :key="item.id" :to="`/admin/law-exam/nuxt/lesson/${item.id}`" class="lesson-card" :class="{ complete: progress.lessons[item.id]?.status === 'completed' }"><div class="number">{{ String(item.order).padStart(2, '0') }}</div><div><span>{{ item.duration }} 分鐘 · {{ statusLabel(item) }}</span><h4>{{ item.title }}</h4><p>{{ item.subtitle }}</p></div><b>→</b></NuxtLink></div></div></section>
    <p v-if="syncError" class="cloud error">⚠️ {{ syncError }}</p><p v-else-if="loaded" class="cloud">☁️ 進度、程式碼與筆記會同步至資料庫，可跨裝置繼續學習。<span v-if="migratedFromBrowser">已完成本機舊資料搬移。</span></p>
  </main>
</template>

